ALTER TABLE public.price_list ADD COLUMN IF NOT EXISTS image_url TEXT; ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS logo_url TEXT; SELECT column_name FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'price_list' AND column_name = 'image_url' UNION ALL SELECT column_name FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'profiles' AND column_name = 'logo_url';